const D=window.CASE_DATA;
const $=(s,root=document)=>root.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rich=v=>esc(v).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>');
const path=p=>p.startsWith('data:')?p:p.split('/').map(encodeURIComponent).join('/');
const list=items=>'<ul>'+items.map(x=>'<li>'+rich(x)+'</li>').join('')+'</ul>';
const sectionHead=(num,title,sub='')=>`<div class="section-heading"><div><p class="eyebrow">${num}</p><h2>${title}</h2></div>${sub?`<span class="muted">${sub}</span>`:''}</div>`;
const reportLink=id=>`<button class="text-button report-link" data-report="${id}">查看原報告 ${id} ↗</button>`;

$('#summary .summary-card').insertAdjacentHTML('beforebegin',`<details class="doctor-note" open><summary>完整交班文字與資料缺口</summary><p>${esc(D.summaryForDoctor)}</p><button id="copySummary">複製交班文字</button><span id="copyStatus" class="muted" role="status"></span><p class="muted top-gap">待補：目前症狀、實際肌力／反射、用藥與過敏、復健反應、家族風濕病史、晨僵／活動反應。尚未收到本人補充，不能判定目前病況穩定。</p></details>`);
$('#summary').insertAdjacentHTML('beforeend',`<div class="inventory"><span><b>${D.counts.images}</b> MRI／X 光影像</span><span><b>4</b> 病歷照片</span><span><b>${D.counts.reportGroups}</b> 組報告內容 / ${D.counts.reports} 原列</span><span><b>${D.counts.labs}</b> 檢驗原列</span></div>`);
$('#content').innerHTML=`
<section id="timeline">${sectionHead('02 · CLINICAL HISTORY','病程與檢查紀錄')}<div class="timeline">${D.timeline.map(x=>`<article><div class="timeline-date">${esc(x.date)}<small>${esc(x.kind)}</small></div><div><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p><p class="source">${esc(x.source)}</p>${x.report?reportLink(x.report):''}</div></article>`).join('')}</div></section>
<section id="imaging">${sectionHead('03 · IMAGE LIBRARY','影像閱覽',`${D.counts.images} 張 · ${D.counts.series} 個序列`)}<div class="callout"><b>日期待核對</b>2026 資料夾 MetaData 寫 2026-08-07、23Y，文字報告為 2026-09-04。以下以資料夾年份分類，並非確認檢查日期；不據此判斷進展。</div><div class="viewer-toolbar"><p class="muted">預覽為 WebP 縮圖，點開才載入 JPEG；缺 DICOM 空間資訊與視窗調整，切片編號不代表解剖層面一一對應。</p><button id="compareBtn" aria-pressed="false">並排對照兩組影像</button></div><div class="viewer-grid" id="viewers"></div><details class="small-detail"><summary>影像檢視範圍與原始中繼資料</summary><p>本次 AI 僅檢視代表性矢狀／STIR 影像，不宣稱逐張完成診斷級判讀。全部 179 張均已納入閱覽器供後續醫師瀏覽。定位片（localizer）不等於專用頸胸 MRI。請使用原院完整 DICOM 核對神經孔、椎管與髖／薦髂結構。</p><div class="two-col">${Object.entries(D.metadata).map(([year,text])=>`<div><b>${year} / MetaData 原文</b><pre>${esc(text)}</pre></div>`).join('')}</div></details></section>
<section id="team">${sectionHead('04 · SPECIALTY REVIEW','四專科研究觀點')}<p class="muted">以下是四個 AI sub agents 依文件與文獻所做的專科視角研究，沒有真人會診或面診。各科的完整分析保留，不取代原醫師意見。</p><div class="tabs" id="teamTabs" role="tablist" aria-label="專科研究">${D.team.map((t,i)=>`<button role="tab" id="tab-${t.id}" aria-selected="${i===0}" aria-controls="teamPanel" data-team="${i}">${['骨科','復健科','神經外科','神經內科'][i]}</button>`).join('')}</div><div id="teamPanel" role="tabpanel"></div></section>
<section id="labs">${sectionHead('05 · LABORATORY','血液檢驗與解讀')}<div class="lab-notes"><article><span class="label">發炎／免疫</span><b>HLA-B27 (−) · ESR 6</b><p>分別來自 2026/09 與 2025/12。ANA 依原文 1:80X(−)、RA &lt;10；未見 CRP。陰性／正常不能單獨排除軸性脊椎關節炎。<a href="https://www.nice.org.uk/guidance/NG65/chapter/Recommendations" target="_blank" rel="noopener noreferrer">NICE NG65 ↗</a></p></article><article><span class="label">肌肉／血栓相關</span><b>CK 107 · D-dimer &lt;0.16</b><p>2025/12 原參考範圍內，僅反映當時。不能排除新發血栓、所有肌病或所有神經問題。</p></article><article><span class="label">血球需留意原值</span><b>MCH 25.8 ↓ · RBC 6.0 ↑</b><p>分別為 2025/12、2026/09；血色素未低於各次原參考值。可請家醫科核對／追蹤血球及視情況鐵狀態，不由單值診斷貧血、缺鐵或地中海型貧血。</p></article></div><div class="controls"><label>檢驗日期<select id="labDate"><option value="all">全部日期</option><option>2026-09-10</option><option>2025-12-09</option></select></label><label class="check"><input type="checkbox" id="labUnique" checked> 合併同次相同結果</label><span id="labCount" class="muted" role="status"></span></div><p class="muted">保留原名稱、單位及參考值；高低提示只比較原檔數值範圍，與「原頁面紅字」分開。百分比的「Platelet 血小板 0.32%」不與 316 的計數合併；原命名需院所核對。</p><div class="table-scroll"><table><thead><tr><th>日期／原列</th><th>項目</th><th>結果</th><th>單位</th><th>原參考值</th><th>備註</th></tr></thead><tbody id="labBody"></tbody></table></div><p class="source">來源：血液檢驗明細 → 工作表「完整明細」，A8:L51；A/B 為不同上傳來源，合併顯示不刪除原列。</p></section>
<section id="originals">${sectionHead('06 · ORIGINAL RECORDS','原始報告與病歷照片')}<div class="record-grid"><article class="panel"><h3>報告原文</h3><label for="reportSelect">選擇報告內容（相同文字合併）</label><select id="reportSelect">${D.reportGroups.map((g,i)=>`<option value="${i}">${esc(g.displayTitle||g.title)}｜原列 ${g.ids.join('、')}</option>`).join('')}</select><div id="reportBody"></div></article><article class="panel"><h3>原醫師門診紀錄</h3><p>元氣診所 · 林昀毅醫師 · 2025/10–12<br><span class="muted">原診斷為未特定腰痛、右大腿痛。照片轉錄與 AI 研究分開保存。</span></p><div class="photo-grid">${D.photos.map((p,i)=>`<button class="photo" data-photo="${i}"><img loading="lazy" decoding="async" src="${path(p.thumb)}" alt="${p.name} 病歷縮圖"><span>${p.name}<small>${['病歷封面','10月／12月病歷','12月病歷與引用報告','NCV／12月門診'][i]}</small></span></button>`).join('')}</div><details class="transcript"><summary>查看完整病歷轉錄（保留截斷標示）</summary><pre>${esc(D.recordText)}</pre></details><p class="muted">縮圖為 WebP；點開才載入 HEIC 轉出的 JPEG 顯示副本，並可取得 HEIC 原件。原件包含個人識別資料。</p></article></div><details class="panel"><summary>全部 23 筆報告原列與本地原始檔</summary><div class="raw-reports">${D.reports.map(r=>`<details><summary>${esc(r.heading)}</summary><pre>${esc(r.metadata)}\n\n${esc(r.body)}</pre></details>`).join('')}</div><div class="downloads">${D.documents.map(d=>`<a href="${path(d.path)}" download>${esc(d.name)} ↓</a>`).join('')}</div></details><div class="panel incidental"><h3>其他所見與資料校正</h3><p><b>L2 0.7 cm 病灶：</b>原放射科描述 T1/T2 高訊號並判為 lipoma；尚無證據把這個小病灶當成腿痛病因，是否追蹤交由原放射科／臨床醫師確認。</p><p><b>腸道病理：</b>2026/03 原文為良性淋巴聚集、無癌證據。多項染色與 A/B 上傳為同段內容；不代表多個腫瘤，也不能推論發炎性腸病。</p><p><b>血管原文：</b>遠端動脈欄有 Biphasic／20–49% 分類，但總結無顯著動脈狹窄；兩者一併保留，勿擅改為「全部完全正常」。靜脈陰性只限當次受檢範圍。</p></div></section>
<section id="diagnoses">${sectionHead('07 · DIFFERENTIAL','診斷方向與下一步')}<p class="muted">依現有證據支持程度由高到低排列；同級可並存，不是數值機率。第一項是已記錄的結構所見，其餘是待驗證病因。低置信度的脊髓病變，若有警訊仍需優先處理。</p><div class="diagnoses">${D.diagnoses.map((x,i)=>`<details class="diagnosis" ${i===0?'open':''}><summary><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="diagnosis-name"><b>${esc(x.name)}</b><small>${esc(x.confidence)}</small></span><span class="status">${esc(x.status)}</span></summary><div class="diagnosis-body"><div><span class="label">支持證據</span><p>${esc(x.support)}</p></div><div><span class="label">反證與不足</span><p>${esc(x.against)}</p></div><div class="next"><span class="label">下一步如何確認</span><p>${esc(x.next)}</p></div><p class="source">依據：${esc(x.source)}</p></div></details>`).join('')}</div><div class="plan"><h3>接下來的就診順序</h3>${D.nextSteps.map((x,i)=>`<div class="step"><span>${i+1}</span><div><b>${esc(x.title)}</b><p>${esc(x.detail)}</p></div></div>`).join('')}</div></section>
<section id="evidence">${sectionHead('08 · EVIDENCE','研究依據與適用限制')}<p class="muted">查核日 2026-09-25。採官方指引、學會共識及原始研究；出版年份不等於證據強度。2026 年新小纖維神經病指引有納入，但本例缺相符表型，不因此提升診斷順位。</p><div id="referenceList"></div><div class="limitations"><h3>如何使用這份整理</h3><p>這是資料整合與可追溯的 AI 推論，沒有實際面診、完整 DICOM 判讀或經驗證的個人罹病機率。重複申報／上傳不當成多次檢查；原報告「未描述」不寫成「已排除」。請後續醫師核對現況，再決定診斷與治療。</p><p>此版不使用外部字型、分析追蹤或自動回傳資料。若部署為網站，影像與病歷會從伺服器傳送到瀏覽器；只有主動點選文獻連結才開啟外部網站。</p></div></section>`;

function renderTeam(index){
 const t=D.team[index];
 $$('#teamTabs button').forEach((b,i)=>{b.setAttribute('aria-selected',i===index);b.tabIndex=i===index?0:-1});
 $('#teamPanel').setAttribute('aria-labelledby','tab-'+t.id);
 $('#teamPanel').innerHTML=`<article class="panel team-panel"><span class="label">${esc(t.specialty)} · AI 分析原文</span><h3>${esc(t.title)}</h3><p class="team-summary">${rich(t.summary)}</p><div class="findings">${t.findings.map(x=>`<div><h4>${esc(x.title)}</h4><p>${rich(x.detail)}</p><p class="source">${rich(x.source)}</p></div>`).join('')}</div><details><summary>此科完整鑑別診斷</summary>${t.differential.map(x=>`<div class="specialty-diff"><b>${esc(x.name)}</b><p class="label">${esc(x.confidence)}</p><p>支持：${rich(x.support)}</p><p>不足：${rich(x.against)}</p><p>下一步：${rich(x.next)}</p></div>`).join('')}</details><details open><summary>此科建議</summary>${list(t.recommendations)}</details><details><summary>急症警訊與分析限制</summary>${list(t.redFlags)}${list(t.limitations)}</details><details><summary>此科研究來源</summary>${t.references.map(refHTML).join('')}</details></article>`;
}
function $$(s,root=document){return [...root.querySelectorAll(s)]}
function refHTML(r){return `<article class="reference"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a><small>${esc(r.date)}</small><p>${esc(r.note)}</p></article>`}
$('#teamTabs').addEventListener('click',e=>{const b=e.target.closest('button');if(b)renderTeam(+b.dataset.team)});
$('#teamTabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let i=+e.target.dataset.team;i=e.key==='Home'?0:e.key==='End'?D.team.length-1:(i+(e.key==='ArrowRight'?1:-1)+D.team.length)%D.team.length;renderTeam(i);$$('#teamTabs button')[i].focus()}});
renderTeam(0);
const refs=[...D.extraReferences,...D.team.flatMap(t=>t.references)];const seenRefs=new Set();$('#referenceList').innerHTML=refs.filter(r=>{const key=r.url.toLowerCase().replace(/\/$/,'');if(seenRefs.has(key))return false;seenRefs.add(key);return true}).map(refHTML).join('');

function renderReport(i){const g=D.reportGroups[i];$('#reportBody').innerHTML=`<p class="source">原列 ${g.ids.join('、')} · ${g.ids.length>1?`相同正文共 ${g.ids.length} 列，不等於多次獨立檢查。`:'單筆報告內容。'}</p><pre>${esc(g.body)}</pre><details><summary>日期、醫事機構與上傳資訊</summary>${g.ids.map(id=>`<h4>原列 ${id}</h4><pre>${esc(D.reports.find(r=>r.id===id).metadata)}</pre>`).join('')}</details>`;}
$('#reportSelect').addEventListener('change',e=>renderReport(+e.target.value));renderReport(0);
$$('.report-link').forEach(b=>b.addEventListener('click',()=>{const i=D.reportGroups.findIndex(g=>g.ids.includes(b.dataset.report));$('#reportSelect').value=i;renderReport(i);$('#originals').scrollIntoView({behavior:'smooth'});$('#reportSelect').focus({preventScroll:true})}));

function renderLabs(){
 let rows=D.labs.filter(r=>$('#labDate').value==='all'||r['檢查日期']===$('#labDate').value).map(r=>({...r,sourceRows:[r['原始列號']],cells:[r.cellRange],sources:[r['資料來源']]}));
 const total=rows.length;
 if($('#labUnique').checked){const m=new Map();for(const r of rows){const k=JSON.stringify([r['檢查日期'],r['檢驗檢查項目名稱'],r['檢查結果'],r['單位'],r['參考值（原文）'],r['醫令代碼'],r['醫事機構']]);if(m.has(k)){const old=m.get(k);old.sourceRows.push(...r.sourceRows);old.cells.push(...r.cells);old.sources.push(...r.sources)}else m.set(k,r)}rows=[...m.values()]}
 $('#labCount').textContent=`顯示 ${rows.length} 項／${total} 原列`;
 $('#labBody').innerHTML=rows.map(r=>`<tr><td>${esc(r['檢查日期'])}<small>原列 ${r.sourceRows.join('、')} · ${[...new Set(r.sources)].join('/')}</small><small>完整明細 ${r.cells.join('、')}</small></td><th scope="row">${esc(r['檢驗檢查項目名稱'])}</th><td class="lab-value ${r.rangeFlag?'flag':''}">${esc(r['檢查結果'])}</td><td>${esc(r['單位'])}</td><td>${esc(r['參考值（原文）'])}</td><td><span class="${r.rangeFlag?'flag':''}">${esc(r.rangeFlag)}</span><small>${esc(r['原頁面標記']||'')}</small></td></tr>`).join('');
}
$('#labDate').addEventListener('change',renderLabs);$('#labUnique').addEventListener('change',renderLabs);renderLabs();

const viewers=[];
function createViewer(id,year){
 const div=document.createElement('article');div.className='viewer';div.id=id;
 div.innerHTML=`<div class="viewer-selects"><label>資料夾<select class="year" aria-label="${id} 資料夾年份"><option>2025</option><option>2026</option></select></label><label>序列<select class="series" aria-label="${id} 影像序列"></select></label></div><button class="image-stage" aria-label="放大目前影像"><img loading="lazy" decoding="async" alt=""></button><div class="slice-controls"><button class="prev" aria-label="上一張">←</button><input class="slice" type="range" min="0" aria-label="切片位置"><button class="next" aria-label="下一張">→</button></div><div class="image-meta"><b class="counter"></b><span class="filename"></span></div><p class="image-hint">點影像放大 · 可滑動切片或按左右鍵</p>`;
 $('#viewers').append(div);const state={div,year,series:null,index:0};viewers.push(state);
 $('.year',div).value=year;
 function chooseSeries(){const choices=D.series.filter(s=>s.year===state.year);$('.series',div).innerHTML=choices.map(s=>`<option value="${s.id}">${esc(s.name)} (${s.images.length})</option>`).join('');state.series=choices.find(s=>s.name==='Sag T2 frFSE')||choices[0];$('.series',div).value=state.series.id;state.index=Math.floor(state.series.images.length/2);update()}
 function update(){const s=state.series;state.index=Math.max(0,Math.min(s.images.length-1,state.index));const im=s.images[state.index];const img=$('img',div);img.src=path(im.thumb);img.alt=`${state.year} 資料夾 ${s.name} ${im.filename} WebP 縮圖`;$('.slice',div).max=s.images.length-1;$('.slice',div).value=state.index;$('.counter',div).textContent=`${state.index+1} / ${s.images.length}`;$('.filename',div).textContent=im.filename;$('.prev',div).disabled=state.index===0;$('.next',div).disabled=state.index===s.images.length-1}
 $('.year',div).onchange=e=>{state.year=e.target.value;chooseSeries()};$('.series',div).onchange=e=>{state.series=D.series.find(s=>s.id===e.target.value);state.index=Math.floor(state.series.images.length/2);update()};$('.slice',div).oninput=e=>{state.index=+e.target.value;update()};$('.prev',div).onclick=()=>{state.index--;update()};$('.next',div).onclick=()=>{state.index++;update()};$('.image-stage',div).onclick=()=>{const im=state.series.images[state.index];openImage(im.path,`${state.year} / ${state.series.name} / ${im.filename}`,im.path)};$('.image-stage',div).onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();state.index+=e.key==='ArrowRight'?1:-1;update()}};chooseSeries();return state;
}
createViewer('viewer-primary','2026');
$('#compareBtn').onclick=()=>{const open=$('#compareBtn').getAttribute('aria-pressed')!=='true';$('#compareBtn').setAttribute('aria-pressed',open);$('#compareBtn').textContent=open?'返回單組閱覽':'並排對照兩組影像';$('#viewers').classList.toggle('compare',open);if(open&&!$('#viewer-secondary'))createViewer('viewer-secondary','2025');if($('#viewer-secondary'))$('#viewer-secondary').hidden=!open;};

document.body.insertAdjacentHTML('beforeend',`<dialog id="imageDialog"><div class="modal-bar"><b id="imageTitle"></b><button id="closeImage" aria-label="關閉影像">關閉 ✕</button></div><div class="modal-tools"><label>放大 <input id="zoomImage" type="range" min="1" max="4" value="1" step="0.25"></label><button id="rotateImage">旋轉 90°</button><a id="downloadImage" download>開啟／下載原檔 ↗</a></div><div id="imageCanvas"><div id="imageWrap"><img id="largeImage" alt=""></div></div><p class="modal-help">放大後可捲動檢視；Esc 可關閉。醫療影像以原報告與完整 DICOM 為準。</p></dialog><div id="printSummary"><h1>就診交班摘要</h1><p>資料整理：2026-09-25 · AI 研究整合，供醫師核對</p><p>${esc(D.summaryForDoctor)}</p><h2>優先問題</h2>${list(D.nextSteps.map(s=>s.title+'：'+s.detail))}<h2>急症警訊</h2><p>新尿滯留／失禁、會陰麻木、快速惡化無力或無法行走請立即急診。</p><p>不等於正式診斷；近期症狀與用藥仍待本人及醫師確認。</p></div>`);
let rotation=0;
function fitLarge(){const img=$('#largeImage'),canvas=$('#imageCanvas'),wrap=$('#imageWrap');if(!img.naturalWidth)return;const z=+$('#zoomImage').value;const rotated=Math.abs(rotation%180)===90;const nw=rotated?img.naturalHeight:img.naturalWidth,nh=rotated?img.naturalWidth:img.naturalHeight;const scale=Math.min((canvas.clientWidth-32)/nw,(canvas.clientHeight-32)/nh,1)*z;const w=img.naturalWidth*scale,h=img.naturalHeight*scale;wrap.style.width=`${rotated?h:w}px`;wrap.style.height=`${rotated?w:h}px`;img.style.width=w+'px';img.style.height=h+'px';img.style.transform=`translate(-50%,-50%) rotate(${rotation}deg)`;}
function openImage(src,title,original){rotation=0;$('#zoomImage').value=1;$('#imageTitle').textContent=title;$('#largeImage').alt=title;$('#largeImage').onload=fitLarge;$('#largeImage').src=path(src);$('#downloadImage').href=path(original);$('#imageDialog').showModal();requestAnimationFrame(fitLarge)}
$('#closeImage').onclick=()=>$('#imageDialog').close();$('#zoomImage').oninput=fitLarge;$('#rotateImage').onclick=()=>{rotation+=90;fitLarge()};window.addEventListener('resize',fitLarge);$('#imageDialog').addEventListener('click',e=>{if(e.target===$('#imageDialog'))$('#imageDialog').close()});$$('.photo').forEach(b=>b.onclick=()=>{const p=D.photos[+b.dataset.photo];openImage(p.path,p.name+' · 病歷原件',p.original)});

$('#copySummary').onclick=async()=>{try{await navigator.clipboard.writeText(D.summaryForDoctor);$('#copyStatus').textContent=' 已複製'}catch{$('#copyStatus').textContent=' 無法存取剪貼簿，請選取上方文字複製。'}};
$('#printBtn').onclick=()=>window.print();
const observer=new IntersectionObserver(items=>{for(const item of items)if(item.isIntersecting){$$('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+item.target.id))}},{rootMargin:'-20% 0px -65% 0px',threshold:0});$$('main section[id]').forEach(s=>observer.observe(s));
